@font-face {
    font-family: "04b09";
    src: url("data:font/truetype;base64,") format("truetype");
    font-display: block;
}

@font-face {
    font-family: "Helvetica Neue";
    src: url("data:font/opentype;base64,") format("opentype");
    font-display: block;
}

@font-face {
    font-family: "Helvetica Neue 97 Black Condensed";
    src: url("data:font/opentype;base64,") format("opentype");
    font-display: block;
}

@font-face {
    font-family: "Helvetica Neue 97 Black Condensed Oblique";
    src: url("data:font/opentype;base64,") format("opentype");
    font-display: block;
}

@font-face {
    font-family: "Iosevka Charon Mono Bold";
    src: url("data:font/truetype;base64,") format("truetype");
    font-display: block;
}

@font-face {
    font-family: "Iosevka Charon Mono Medium";
    src: url("data:font/truetype;base64,") format("truetype");
    font-display: block;
}

@font-face {
    font-family: "Trade Gothic Next LT Pro BdCn";
    src: url("data:font/truetype;base64,") format("truetype");
    font-display: block;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
    width: 100%; height: 100%;
    background: transparent;
    overflow: hidden;
}

canvas {
    position: absolute; display: block;
}
